import type {StackContext} from 'sst/constructs';
import {Api, use} from 'sst/constructs';
import {AppConfig} from './AppConfig';

/**
 * Configure an API Gateway instance
 */
export function BffApi({stack, app}: StackContext) {
  const {hostedZone, target, featureAppName} = use(AppConfig);
  const baseUrl = `/__app__/${featureAppName}/${target}`;

  const isLocal = app.local;

  const api = new Api(stack, `api`, {
    customDomain: {
      hostedZone,
      domainName: isLocal
        ? `bff.${stack.stage}.${hostedZone}`
        : `bff.${hostedZone}`,
    },
    routes: {
      [`ANY ${baseUrl}/bff/{proxy+}`]: {
        function: {
          handler: `src/bff/index.handler`,
          functionName: `BFF-TRPC-${target.toUpperCase()}-ANY-catch-all-${stack.stage}`,
          description: `BFF TRPC ANY catch-all function for ${target} in stage ${stack.stage}`,
        },
      },
    },
  });

  stack.addOutputs({
    apiUrl: api.customDomainUrl ?? api.url,
  });

  return api;
}

